#ifndef A20_CLUSTER_MEMBERSHIP_H
#define A20_CLUSTER_MEMBERSHIP_H
#include "cluster_directory.h"

#define A20_MEMBER_EMPTY 0u
#define A20_MEMBER_ALIVE 1u
#define A20_MEMBER_SUSPECT 2u
#define A20_MEMBER_DEAD 3u
#define A20_MEMBER_MAX_OPERATORS 8u

/* Caller-owned bounded tables. Only the control-plane owner mutates them.
 * Epochs are opaque boot identities, not ordered clocks. Probe cookies are
 * monotonically generated by the owner and never reused during its lifetime. */
typedef struct a20_member {
    uint8_t node_id[16];
    uint32_t state, caps, profile, load;
    uint64_t boot_epoch, incarnation, last_seen, state_deadline;
    uint64_t probe_cookie, probe_deadline;
} a20_member_t;
typedef struct a20_member_operator {
    uint32_t id, flags, max_input, max_output;
} a20_member_operator_t;
typedef struct a20_member_service {
    uint32_t used, member_index, slot, name_len, kinds, max_inflight;
    uint32_t max_input, max_output, operator_count;
    uint64_t boot_epoch, generation, expires;
    char name[64];
    a20_member_operator_t operators[A20_MEMBER_MAX_OPERATORS];
} a20_member_service_t;
typedef struct a20_membership {
    a20_member_t *members;
    a20_member_service_t *services;
    uint32_t member_capacity, service_capacity, cursor;
    uint64_t next_cookie, probe_ms, suspect_ms, tombstone_ms;
} a20_membership_t;

static inline int a20_member_capabilities(a20_member_service_t *s,
                                          const a20_work_result_t *result) {
    if (!s || !result || result->status ||
        result->output_len < A20_WORK_CAP_BYTES)
        return -1;
    const uint8_t *p = result->output;
    uint32_t count = a20_work_u32(p + 20);
    if (count > A20_MEMBER_MAX_OPERATORS ||
        result->output_len !=
            A20_WORK_CAP_BYTES + count * A20_WORK_DESCRIPTOR_BYTES ||
        (a20_work_u32(p) & ~(A20_WORK_CAP_OPERATOR | A20_WORK_CAP_PROCESS)) ||
        !a20_work_u32(p + 12) || !a20_work_u32(p + 16))
        return -1;
    a20_member_service_t copy = *s;
    copy.kinds = a20_work_u32(p);
    copy.max_input = a20_work_u32(p + 4);
    copy.max_output = a20_work_u32(p + 8);
    copy.max_inflight = a20_work_u32(p + 12);
    copy.operator_count = count;
    if (!!count != !!(copy.kinds & A20_WORK_CAP_OPERATOR))
        return -1;
    for (uint32_t i = 0; i < count; i++) {
        const uint8_t *d =
            p + A20_WORK_CAP_BYTES + i * A20_WORK_DESCRIPTOR_BYTES;
        a20_member_operator_t *op = &copy.operators[i];
        *op =
            (a20_member_operator_t){a20_work_u32(d), a20_work_u32(d + 4),
                                    a20_work_u32(d + 8), a20_work_u32(d + 12)};
        if (!op->id || op->max_input > copy.max_input ||
            op->max_output > copy.max_output ||
            (op->flags & ~(A20_WORK_REPLAY_SAFE | A20_WORK_ASSOCIATIVE)))
            return -1;
        for (uint32_t j = 0; j < i; j++)
            if (copy.operators[j].id == op->id)
                return -1;
    }
    *s = copy;
    return 0;
}

static inline int a20_member_refute(uint64_t suspected,
                                    uint64_t *self_incarnation) {
    if (!self_incarnation || suspected == UINT64_MAX)
        return -1;
    if (*self_incarnation <= suspected)
        *self_incarnation = suspected + 1;
    return 0;
}

static inline int a20_member_id_equal(const uint8_t a[16],
                                      const uint8_t b[16]) {
    for (unsigned i = 0; i < 16; i++)
        if (a[i] != b[i])
            return 0;
    return 1;
}
static inline void a20_member_forget_services(a20_membership_t *m,
                                              uint32_t member) {
    for (uint32_t i = 0; i < m->service_capacity; i++)
        if (m->services[i].used && m->services[i].member_index == member)
            m->services[i].used = 0;
}
static inline int
a20_membership_init(a20_membership_t *m, a20_member_t *members,
                    uint32_t member_count, a20_member_service_t *services,
                    uint32_t service_count, uint64_t probe_ms,
                    uint64_t suspect_ms, uint64_t tombstone_ms) {
    if (!m || !members || !services || !member_count || !service_count ||
        !probe_ms || suspect_ms < probe_ms || tombstone_ms < suspect_ms)
        return -1;
    *m = (a20_membership_t){.members = members,
                            .services = services,
                            .member_capacity = member_count,
                            .service_capacity = service_count,
                            .probe_ms = probe_ms,
                            .suspect_ms = suspect_ms,
                            .tombstone_ms = tombstone_ms};
    for (uint32_t i = 0; i < member_count; i++)
        members[i] = (a20_member_t){0};
    for (uint32_t i = 0; i < service_count; i++)
        services[i] = (a20_member_service_t){0};
    return 0;
}
static inline int a20_member_add(a20_membership_t *m, const uint8_t node[16]) {
    if (!m || !node)
        return -1;
    unsigned any = 0, all = 255;
    for (unsigned i = 0; i < 16; i++) {
        any |= node[i];
        all &= node[i];
    }
    if (!any || all == 255)
        return -1;
    int empty = -1;
    for (uint32_t i = 0; i < m->member_capacity; i++) {
        a20_member_t *r = &m->members[i];
        if (r->state && a20_member_id_equal(r->node_id, node))
            return (int)i;
        if (!r->state && empty < 0)
            empty = (int)i;
    }
    if (empty >= 0) {
        a20_member_t *r = &m->members[empty];
        for (unsigned i = 0; i < 16; i++)
            r->node_id[i] = node[i];
        r->state = A20_MEMBER_SUSPECT;
        /* Unknown seeds are not selectable until a correlated probe succeeds. */
    }
    return empty;
}
static inline uint64_t a20_member_probe(a20_membership_t *m, uint32_t index,
                                        uint64_t now) {
    if (!m || index >= m->member_capacity || !m->members[index].state ||
        m->members[index].probe_cookie || m->next_cookie == UINT64_MAX)
        return 0;
    a20_member_t *r = &m->members[index];
    r->probe_cookie = ++m->next_cookie;
    r->probe_deadline = now + m->probe_ms;
    return r->probe_cookie;
}

/* Indirect results can confirm only an already known epoch. A helper cannot
 * invent a reboot or replace a direct peer's boot identity. Both paths must
 * echo the current outstanding probe cookie before its deadline. */
static inline int a20_member_observe(a20_membership_t *m, uint32_t index,
                                     uint64_t cookie, uint64_t epoch,
                                     uint64_t incarnation, uint32_t caps,
                                     uint32_t profile, uint64_t now,
                                     int direct) {
    if (!m || index >= m->member_capacity || !epoch || profile < 1 ||
        profile > 3)
        return -1;
    a20_member_t *r = &m->members[index];
    if (!r->state || !cookie || r->probe_cookie != cookie ||
        now >= r->probe_deadline || (!direct && r->boot_epoch != epoch) ||
        (r->boot_epoch == epoch && incarnation < r->incarnation))
        return -1;
    if (r->boot_epoch != epoch) {
        a20_member_forget_services(m, index);
        r->incarnation = incarnation;
    } else if (incarnation > r->incarnation) {
        r->incarnation = incarnation;
    }
    r->boot_epoch = epoch;
    r->caps = caps;
    r->profile = profile;
    r->last_seen = now;
    r->state = A20_MEMBER_ALIVE;
    r->state_deadline = 0;
    r->probe_cookie = 0;
    return 0;
}

static inline void a20_membership_tick(a20_membership_t *m, uint64_t now) {
    for (uint32_t i = 0; i < m->member_capacity; i++) {
        a20_member_t *r = &m->members[i];
        if (r->probe_cookie && now >= r->probe_deadline) {
            r->probe_cookie = 0;
            if (r->state == A20_MEMBER_ALIVE || !r->state_deadline) {
                r->state = A20_MEMBER_SUSPECT;
                r->state_deadline = now + m->suspect_ms;
            }
        }
        if (r->state == A20_MEMBER_SUSPECT && r->state_deadline &&
            now >= r->state_deadline) {
            r->state = A20_MEMBER_DEAD;
            r->state_deadline = now + m->tombstone_ms;
            a20_member_forget_services(m, i);
        } else if (r->state == A20_MEMBER_DEAD && !r->probe_cookie &&
                   now >= r->state_deadline) {
            *r = (a20_member_t){0};
        }
    }
    for (uint32_t i = 0; i < m->service_capacity; i++)
        if (m->services[i].used && now >= m->services[i].expires)
            m->services[i].used = 0;
}

/* Rumors never add a node, change a boot epoch, or revive dead membership.
 * A successful correlated probe is required for availability. */
static inline int a20_member_suspect(a20_membership_t *m, uint32_t index,
                                     uint64_t epoch, uint64_t incarnation,
                                     uint64_t now) {
    if (!m || index >= m->member_capacity)
        return -1;
    a20_member_t *r = &m->members[index];
    if (!r->state || r->boot_epoch != epoch || incarnation < r->incarnation ||
        r->state == A20_MEMBER_DEAD)
        return -1;
    if (r->state == A20_MEMBER_ALIVE) {
        r->state = A20_MEMBER_SUSPECT;
        r->state_deadline = now + m->suspect_ms;
    }
    r->incarnation = incarnation;
    return 0;
}

/* Commit a complete, generation-consistent directory after END. Validate
 * every entry and total capacity before replacing the previous snapshot. */
static inline int a20_member_publish(a20_membership_t *m, uint32_t index,
                                     const a20_member_service_t *records,
                                     uint32_t count, uint64_t generation,
                                     uint64_t lease_ms, uint64_t now) {
    if (!m || index >= m->member_capacity || (count && !records) ||
        !generation || !lease_ms ||
        m->members[index].state != A20_MEMBER_ALIVE ||
        !m->members[index].boot_epoch)
        return -1;
    uint32_t space = 0;
    for (uint32_t i = 0; i < m->service_capacity; i++)
        if (!m->services[i].used || m->services[i].member_index == index)
            space++;
    if (count > space)
        return -1;
    for (uint32_t i = 0; i < count; i++) {
        const a20_member_service_t *r = &records[i];
        if (!r->slot || r->slot >= A20_DIRECTORY_SLOT || !r->name_len ||
            r->name_len > 64 || r->operator_count > A20_MEMBER_MAX_OPERATORS ||
            (r->kinds & ~(A20_WORK_CAP_OPERATOR | A20_WORK_CAP_PROCESS)) ||
            !r->max_inflight)
            return -1;
        for (uint32_t j = 0; j < i; j++) {
            if (records[j].slot == r->slot)
                return -1;
            if (records[j].name_len == r->name_len) {
                uint32_t k = 0;
                while (k < r->name_len && records[j].name[k] == r->name[k])
                    k++;
                if (k == r->name_len)
                    return -1;
            }
        }
    }
    a20_member_forget_services(m, index);
    uint32_t next = 0;
    for (uint32_t i = 0; i < m->service_capacity && next < count; i++) {
        if (m->services[i].used)
            continue;
        m->services[i] = records[next++];
        m->services[i].used = 1;
        m->services[i].member_index = index;
        m->services[i].boot_epoch = m->members[index].boot_epoch;
        m->services[i].generation = generation;
        m->services[i].expires = now + lease_ms;
    }
    return 0;
}

/* Round-robin among eligible alive services. Selection does not reserve
 * capacity; the scheduler owns admission accounting using max_inflight. */
static inline int a20_member_select(a20_membership_t *m, const char *name,
                                    uint32_t name_len, uint32_t kind,
                                    uint32_t operator_id, uint32_t input_len,
                                    uint64_t now) {
    if (!m || !name || !name_len || name_len > 64 ||
        (kind != A20_WORK_OPERATOR && kind != A20_WORK_PROCESS))
        return -1;
    for (uint32_t j = 0; j < m->service_capacity; j++) {
        uint32_t i = (m->cursor + j) % m->service_capacity;
        a20_member_service_t *s = &m->services[i];
        if (!s->used || s->member_index >= m->member_capacity ||
            s->expires <= now || s->name_len != name_len ||
            input_len > s->max_input)
            continue;
        a20_member_t *r = &m->members[s->member_index];
        if (r->state != A20_MEMBER_ALIVE || r->boot_epoch != s->boot_epoch)
            continue;
        uint32_t k = 0;
        while (k < name_len && s->name[k] == name[k])
            k++;
        if (k != name_len)
            continue;
        if (kind == A20_WORK_PROCESS) {
            if (!(s->kinds & A20_WORK_CAP_PROCESS) || operator_id != 1 ||
                input_len)
                continue;
        } else {
            if (!(s->kinds & A20_WORK_CAP_OPERATOR))
                continue;
            for (k = 0; k < s->operator_count; k++)
                if (s->operators[k].id == operator_id &&
                    input_len <= s->operators[k].max_input)
                    break;
            if (k == s->operator_count)
                continue;
        }
        m->cursor = (i + 1) % m->service_capacity;
        return (int)i;
    }
    return -1;
}
#endif
